    checkOutputFolderCount(1);
    HashMap<Long, Long> counts = loadOutputCounts("20130317");
    checkSize(counts, 3);
    checkIdCount(counts, 1, 13);
    checkIdCount(counts, 2, 14);
    checkIdCount(counts, 3, 15);
    openDayForEvent(2013, 3, 18);
    storeIds(1, 1);
    storeIds(2, 2, 2, 2, 2);
    storeIds(3, 3, 3, 3);
    storeIds(4, 4, 4);
