    Map<Integer, Integer> valuesPerKey = new HashMap<Integer, Integer>();
    // 10,000 keys total
    for (int i = 0; i < 10000; i++) {
        // 5 values per key
        for (int j = 0; j < 5; j++) {
            Tuple t = TupleFactory.getInstance().newTuple(1);
            t.set(0, i);
            if (sampler.exec(t)) {
